"use strict";(function(){const SECTION_SELECTOR=".Gstore-home-blog";const QUERY_SELECTOR=".wp-block-query.Gstore-home-blog__query";const PAGINATION_LINK_SELECTOR=".Gstore-home-blog__pagination a";let activeController=null;let requestId=0;let initialized=false;function getSection(){return document.querySelector(SECTION_SELECTOR)}function getQueryBlock(section){return section?section.querySelector(QUERY_SELECTOR):null}function shouldHandleClick(event,link){if(!link||event.defaultPrevented){return false}if(event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey){return false}const href=link.getAttribute("href");if(!href||href.charAt(0)==="#"){return false}const target=link.getAttribute("target");if(target&&target!=="_self"){return false}return true}function parseNextQueryBlock(html){const parser=new window.DOMParser;const doc=parser.parseFromString(html,"text/html");return doc.querySelector(SECTION_SELECTOR+" "+QUERY_SELECTOR)}async function fetchAndSwap(url,updateHistory){const section=getSection();const currentQuery=getQueryBlock(section);if(!section||!currentQuery){return false}if(activeController){activeController.abort()}const controller=new AbortController;activeController=controller;requestId+=1;const thisRequestId=requestId;section.setAttribute("aria-busy","true");currentQuery.classList.add("is-loading");try{const response=await window.fetch(url,{method:"GET",credentials:"same-origin",signal:controller.signal,headers:{"X-Requested-With":"XMLHttpRequest"}});if(!response.ok){throw new Error("Erro HTTP "+response.status)}const html=await response.text();const nextQuery=parseNextQueryBlock(html);if(!nextQuery){throw new Error("Nao foi possivel localizar o bloco de artigos da home na resposta.")}currentQuery.innerHTML=nextQuery.innerHTML;if(updateHistory){window.history.pushState({gstoreHomeBlogUrl:url},"",url)}return true}catch(error){if(error&&error.name==="AbortError"){return null}return false}finally{if(activeController===controller){activeController=null}if(thisRequestId===requestId){section.removeAttribute("aria-busy");currentQuery.classList.remove("is-loading")}}}function handleClick(event){const section=getSection();if(!section){return}const link=event.target.closest(PAGINATION_LINK_SELECTOR);if(!shouldHandleClick(event,link)){return}let targetUrl;try{targetUrl=new URL(link.href,window.location.href)}catch(error){return}if(targetUrl.origin!==window.location.origin){return}event.preventDefault();const url=targetUrl.toString();fetchAndSwap(url,true).then(function(status){if(status===false){window.location.assign(url)}})}function handlePopState(){const section=getSection();if(!section){return}fetchAndSwap(window.location.href,false)}function init(){if(initialized){return}const section=getSection();if(!section){return}section.addEventListener("click",handleClick);window.addEventListener("popstate",handlePopState);initialized=true}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init)}else{init()}})();
